/* Production mode. The local prototype remains available through preview.cjs. */
if(window.OROO_CONFIG?.mode==='cloud'){
const cloud={searchUpdated:0,ready:false,user:null,csrf:null,cache:new Map(),items:[],cursor:null,error:'',searchKey:'',searchAbort:null,bounds:null,markers:[],saving:false,uploads:0};
const cloudOriginal={home,render,flowRoute,detail,imageFor,editor:renderListingEditor,capture:captureListingDraft,sync:syncListingPhotos,submit:submitListingEditor,mapMarkup:propertyMapMarkup,detailMarkup:listingDetailMarkup,card};
const cloudLabels={clients:'Харилцагчид',consultations:'Зөвлөгөө',schedules:'Хуваарь',contracts:'Гэрээний бүртгэл',ledger:'Орлого / зарлага',groups:'Бүлгүүд',campaigns:'Зар сурталчилгааны хүсэлт',inquiries:'Лавлагаа',reports:'Мэдээлсэн зарууд',support:'Тусламж',posts:'Хөршүүдийн түүх',notices:'Мэдээ'};
const cloudStatuses={pending:'Хянаж байна',approved:'Баталсан',rejected:'Татгалзсан',suspended:'Түр зогсоосон',published:'Нийтэлсэн',hidden:'Нуусан',closed:'Дууссан',deleted:'Архив',draft:'Ноорог',new:'Шинэ',active:'Идэвхтэй',first_review:'Хоёр дахь хяналт хүлээж байна',archived:'Архив',progress:'Шийдвэрлэж байна',resolved:'Шийдвэрлэсэн',blocked:'Хаасан'};
function cloudError(error){const messages={login_required:'Эхлээд нэвтэрнэ үү.',invalid_login:'Имэйл эсвэл нууц үгээ шалгана уу.',invalid_csrf:'Нэвтрэх хугацаа дууссан. Дахин нэвтэрнэ үү.',permission_denied:'Энэ хэсэгт нэвтрэх эрхгүй.',revision_conflict:'Мэдээлэл өөрчлөгдсөн. Шинэчилж дахин шалгана уу.',organization_required:'Эхлээд байгууллагаа бүртгэнэ үү.',photos_required:'Байрны бодит зургаас нэмнэ үү.',rate_limited:'Хэт олон хүсэлт. Түр хүлээнэ үү.',password_length:'Нууц үг 15–128 тэмдэгттэй байна.',account_unavailable:'Энэ имэйл бүртгэлтэй байж болно. Нэвтрэхийг оролдоно уу.',independent_reviewer_required:'Өөр эрх бүхий ажилтан давхар шалгах шаардлагатай.',invalid_activation:'Идэвхжүүлэх холбоос хүчингүй эсвэл хугацаа дууссан.'};return messages[error.code]||((error.message&&error.message!==error.code)?error.message:'Хүсэлт амжилтгүй. Мэдээллээ шалгаад дахин оролдоно уу.')}
async function cloudAPI(path,options={}){const method=options.method||'GET',headers={...(options.headers||{})};let body=options.body;if(method!=='GET'){headers['x-csrf-token']=cloud.csrf||'';if(!(body instanceof Blob)){headers['content-type']='application/json';body=JSON.stringify(body||{})}}let response;try{response=await fetch('/api'+path,{credentials:'same-origin',cache:'no-store',...options,method,headers,body})}catch(error){if(error.name==='AbortError')throw error;throw Object.assign(new Error('Холболтоо шалгаад дахин оролдоно уу.'),{code:'network_error'})}const data=await response.json();if(!response.ok)throw Object.assign(new Error(data.message),{code:data.error,status:response.status,requestId:data.requestId});return data}
function cloudInvalidate(){cloud.cache.clear();cloud.searchKey=''}
function cloudLoad(path){let entry=cloud.cache.get(path);if(!entry){entry={loading:true};const routeAtStart=location.hash;cloud.cache.set(path,entry);cloudAPI(path).then(data=>{entry.loading=false;entry.data=data;cloudRemember(data.items||data.listings?.items||[]);if(location.hash===routeAtStart)render()}).catch(error=>{entry.loading=false;entry.error=error;if(location.hash===routeAtStart)render()})}return entry}
function cloudRemember(items){for(const item of items){if(!item.cloud)continue;const at=homes.findIndex(h=>h.id===item.id);if(at>=0)homes[at]=item;else homes.push(item)}if(homes.length>600){const keep=new Set([...cloud.items.map(h=>h.id),...flowState.listings.map(h=>h.id),activeDetail]);for(let i=homes.length-1;i>=0&&homes.length>600;i--)if(!keep.has(homes[i].id))homes.splice(i,1)}}
function cloudNotice(entry){return entry.error?`<div class="empty" role="alert"><b>${esc(cloudError(entry.error))}</b><button onclick="cloudInvalidate();render()">Дахин оролдох</button></div>`:'<div class="empty" role="status">Ачаалж байна…</div>'}
function cloudBadge(value){return `<span class="cloud-badge ${esc(value||'pending')}">${esc(cloudStatuses[value]||value||'Хянаж байна')}</span>`}
function cloudPage(title,body,menu=''){return `<div class="cloud-workspace">${menu?`<aside class="cloud-sidebar"><a class="cloud-brand" href="#/"><img src="assets/oroo.png" alt="Өрөө" width="95"></a>${menu}</aside>`:''}<section class="cloud-content"><div class="cloud-heading"><div><div class="eyebrow">ӨРӨӨ · СЕРВЕРТ ХОЛБОГДСОН</div><h1>${esc(title)}</h1></div><button onclick="cloudInvalidate();render()">${icon('refresh')} Шинэчлэх</button></div>${body}</section></div>`}
function cloudGate(){return `<div class="wrap cloud-gate">${emptyFlow('Нэвтэрч үргэлжлүүлнэ үү','Бүртгэлтэй хэрэглэгчийн мэдээлэл серверт тусдаа хадгалагдана.','<a class="primary button-link" href="#/login">Нэвтрэх</a>')}</div>`}
function cloudFormError(form,error){const box=form.querySelector('[data-cloud-error]');if(box){box.textContent=cloudError(error);box.hidden=false}else toast(cloudError(error))}
function cloudPendingForm(form,busy){form.querySelectorAll('button[type="submit"],button:not([type])').forEach(b=>b.disabled=busy);form.setAttribute('aria-busy',String(busy))}
function cloudDraftKey(){return 'oroo-cloud-draft:'+cloud.user?.id}
persistFlows=function(){if(!cloud.ready)return true;try{if(cloud.user){const draft={...flowState.draft,photos:(flowState.draft?.photos||[]).filter(src=>/^\/api\/media\/[a-f0-9-]{36}\/full$/.test(src))};localStorage.setItem(cloudDraftKey(),JSON.stringify(draft))}localStorage.setItem('oroo-search-preferences',JSON.stringify({searches:flowState.searches,bookmarks:flowState.bookmarks}));return true}catch{return false}};
isPublicListing=function(h){return !!(h?.cloud&&h.moderationStatus==='approved'&&h.listingStatus==='published'&&(!h.brokerId||h.brokerVerified))};
imageFor=function(h,index=0){if(h?.cloud){const media=h.media?.[index];return media?.thumbUrl||h.photos?.[index]||'assets/listing-placeholder.svg'}return cloudOriginal.imageFor(h,index)};
card=function(h){return cloudOriginal.card(h).replace(/<button class="card-building-link"[\s\S]*?<\/button>/,'')};

home=function(){const html=cloudOriginal.home();return html.replace(/<section class="wrap"><div class="section-head"><h2>Шинэ төслийн мэдээлэл<\/h2>[\s\S]*?<\/section>/,'').replace('<div class="cards"></div>','<div class="cards">'+emptyFlow('Нийтэд нээлттэй зар хараахан байхгүй','Шинэ зар нэмэх эсвэл дараа дахин шалгана уу.','<a href="#/listing/new">Зар нэмэх</a>')+'</div>').replaceAll('#Террастай','#Тагттай').replace('Хотхоны мэдээлэл, бодит хэлцлийн үнэ','Хаус, амины орон сууцны сонголт').replace('Солонгост гэрээ олох хялбар боллоо','Монголд орон зайгаа олоорой').replace('<em>Сүхбаатар</em> орчимд танд санал болгох зарууд','Танд санал болгох зарууд')};
recommendationHomes=function(){return cloud.items.filter(isPublicListing)};
proTrackView=function(){};decorateCommunity=function(){};mountNeighborhoodMap=function(){};mountOfficePage=function(){};
localNotice=function(){return '<p class="notice">Мэдээлэл таны бүртгэлд серверээр хадгалагдана.</p>'};

mobileMorePage=function(){return '<div class="wrap mobile-more-page"><section class="mobile-profile"><div class="mobile-avatar">'+icon('user')+'</div><div><span>ӨРӨӨ · МИНИЙ БУЛАН</span><h1>'+esc(cloud.user?.name||'Тавтай морил!')+'</h1></div><a href="#/'+(cloud.user?'my/profile':'login')+'">'+(cloud.user?'Мэдээлэл засах':'Нэвтрэх / Бүртгүүлэх')+icon('chevron-right')+'</a></section>'+mobileMenuGroup('Миний үйл ажиллагаа',[['my/listings','apartment','Миний зарууд'],['my/messages','message','Лавлагаа'],['my/posts','file-text','Миний нийтлэлүүд'],['my/profile','user-circle','Миний мэдээлэл'],['favorites','heart','Сонирхсон'],['listing/new','plus','Зар нэмэх']])+mobileMenuGroup('Өрөөтэй хамт',[['community','users','Манай хороолол'],['offices','briefcase','Зуучлалын байгууллагууд'],['pro','briefcase','Өрөө PRO'],...(['admin','moderator'].includes(cloud.user?.role)?[['admin','shield','Өрөө ADMIN']]:[]),['inquiry','message','Тусламж / Хүсэлт'],['notice','bell','Мэдээ']])+(cloud.user?'<button class="button-link" onclick="cloudLogout()">'+icon('logout')+'Гарах</button>':'<a class="button-link primary" href="#/login/signup">Бүртгүүлэх</a>')+'<p class="mobile-version">Өрөө · Мэдээлэл таны бүртгэлд серверээр хадгалагдана.</p></div>'};
refreshAccount=function(){const host=document.getElementById('account-control');if(!host)return;host.innerHTML=`<button class="account-trigger" aria-expanded="false" onclick="toggleAccount(this)">${icon('user-circle')}<span>${cloud.user?esc(cloud.user.name):'Нэвтрэх · Миний булан'}</span>${icon('chevron-down')}</button><div class="account-dropdown" hidden><a href="#/my/listings">Миний зарууд</a><a href="#/my/messages">Лавлагаа</a><a href="#/my/profile">Миний мэдээлэл</a><a href="#/pro">Өрөө PRO</a>${['admin','moderator'].includes(cloud.user?.role)?'<a href="#/admin">Өрөө ADMIN</a>':''}${cloud.user?'<button onclick="cloudLogout()">Гарах</button>':'<a href="#/login">Нэвтрэх / Бүртгүүлэх</a>'}</div>`};
async function cloudLogout(){try{await cloudAPI('/auth/logout',{method:'POST'});location.replace(location.pathname+'#/')}catch(error){toast(cloudError(error))}}
function cloudAuth(mode){const signup=mode==='signup',activate=location.hash.startsWith('#/activate-admin');return `<section class="login flow-auth cloud-auth"><a class="logo" href="#/"><img src="assets/oroo.png" alt="Өрөө"></a><h1>${activate?'Админы бүртгэл идэвхжүүлэх':signup?'Шинэ бүртгэл':'Тавтай морил!'}</h1><form onsubmit="cloudAuthenticate(event,'${activate?'activate-admin':signup?'register':'login'}')">${signup?field('Таны нэр','name','','text','required maxlength="60" autocomplete="name"'):''}${activate?'':field('Имэйл','email','','email','required autocomplete="email" maxlength="254"')}<label class="field">Нууц үг<input name="password" type="password" required ${signup||activate?'minlength="15"':''} maxlength="128" autocomplete="${signup||activate?'new-password':'current-password'}"></label>${signup||activate?'<p class="muted">15-аас дээш тэмдэгттэй, бусад сайтад ашиглаагүй нууц үг сонгоно уу.</p>':''}<p class="cloud-error" data-cloud-error role="alert" hidden></p><button class="primary" type="submit">${activate?'Идэвхжүүлэх':signup?'Бүртгүүлэх':'Нэвтрэх'}</button></form>${activate?'':`<div class="auth-links"><a href="#/login/${signup?'email':'signup'}">${signup?'Бүртгэлтэй бол нэвтрэх':'Шинэ бүртгэл үүсгэх'}</a></div><p class="notice">Имэйлээр нууц үг сэргээх болон DAN баталгаажуулалт хараахан холбогдоогүй.</p>`}</section>`}
async function cloudAuthenticate(event,mode){event.preventDefault();const form=event.target;if(form.getAttribute('aria-busy')==='true')return;const body=Object.fromEntries(new FormData(form));if(mode==='activate-admin')body.token=new URLSearchParams(location.hash.split('?')[1]||'').get('token')||'';cloudPendingForm(form,true);try{const result=await cloudAPI('/auth/'+mode,{method:'POST',body});cloud.user=result.user;cloud.csrf=result.csrf;cloudInvalidate();flowState.profile={name:cloud.user.name,demo:false};flowState.draft={};try{flowState.draft=JSON.parse(localStorage.getItem(cloudDraftKey())||'{}')}catch{}editorReady=false;history.replaceState(null,'',location.pathname+'#/'+(['admin','moderator'].includes(cloud.user.role)?'admin':'my/listings'));await cloudLoadOwn();render()}catch(error){cloudFormError(form,error)}finally{cloudPendingForm(form,false)}}
async function cloudLoadOwn(){if(!cloud.user)return;const result=await cloudAPI('/me/listings?limit=30');flowState.listings=result.items;cloudRemember(result.items);cloud.cache.set('/me/listings?limit=30',{data:result});const fav=await cloudAPI('/favorites');saved=fav.ids}
function cloudListingRows(entry,admin=false){if(!entry.data)return cloudNotice(entry);if(!entry.data.items.length)return emptyFlow('Зар байхгүй','Шинэ зар нэмэх боломжтой.','<a href="#/listing/new">Зар нэмэх</a>');return `<div class="cloud-list">${entry.data.items.map(h=>`<article class="cloud-list-row"><img loading="lazy" src="${imageFor(h)}" alt="Байрны зураг"><div><b>${esc(h.name)}</b><p>№ ${h.id} · ${esc(h.area)} · ${esc(propertyPriceText(h))}</p>${cloudBadge(h.moderationStatus)} ${h.moderationStatus==='approved'?cloudBadge(h.listingStatus):''}${h.reviewReason?`<p>${esc(h.reviewReason)}</p>`:''}</div><div class="cloud-row-actions"><button onclick="${admin?'cloudInspect':'cloudPreview'}(${h.id})">Дэлгэрэнгүй</button>${admin?`<button onclick="cloudReviewListing(${h.id},${h.revision})">Хянах</button>`:`<button onclick="editLocalListing(${h.id})">Засах</button><button onclick="cloudArchiveListing(${h.id})">Архивлах</button>`}</div></article>`).join('')}</div>${entry.data.cursor?`<button class="cloud-more" onclick="cloudMoreResource('${admin?'/admin/listings?limit=30':'/me/listings?limit=30'}')">Дараах 30 зар</button>`:''}`}
async function cloudMoreResource(path){const entry=cloud.cache.get(path);if(!entry?.data?.cursor)return;try{const next=await cloudAPI(path+(path.includes('?')?'&':'?')+'cursor='+encodeURIComponent(entry.data.cursor));entry.data={...next,items:[...entry.data.items,...next.items]};cloudRemember(next.items);if(path.startsWith('/me/listings'))flowState.listings=entry.data.items;render()}catch(error){toast(cloudError(error))}}
async function cloudArchiveListing(id){modal(`<h2>Зар архивлах</h2><p>Зар нийтэд харагдахаа болино. Бүртгэл серверт үлдэнэ.</p><button class="primary" onclick="cloudArchiveConfirmed(${id})">Архивлах</button>`)}
async function cloudArchiveConfirmed(id){try{await cloudAPI('/listings/'+id,{method:'DELETE'});cloudInvalidate();await cloudLoadOwn();const at=homes.findIndex(h=>h.id===id);if(at>=0)homes.splice(at,1);closeOverlay();render();toast('Архивлалаа')}catch(error){toast(cloudError(error))}}
async function cloudInspect(id){try{const {item}=await cloudAPI('/listings/'+id);modal(`<h2>${esc(item.name)}</h2><div class="cloud-preview-images">${item.photos.map(src=>`<img src="${src}" alt="Байрны зураг">`).join('')}</div>${listingPriceRows(item)}${listingInfoRows(item)}<h3>Зарын байршил</h3>${listingMapCanvas('listing-saved-map')}<p>${esc(listingPinText(item))}</p><p>${esc(item.description)}</p>${listingContactRows(item)}`);const host=document.getElementById('listing-saved-map'),point=listingPin(item);if(host&&point){listingSavedMap=createListingPinMap(host,point,false);if(listingSavedMap){new maplibregl.Marker({color:'#ff385c'}).setLngLat([point.lng,point.lat]).addTo(listingSavedMap);if(typeof ResizeObserver!=='undefined'){listingSavedObserver=new ResizeObserver(()=>listingSavedMap?.resize());listingSavedObserver.observe(host)}}}}catch(error){toast(cloudError(error))}}
async function cloudPreview(id){await cloudInspect(id)}
previewSavedListingLocation=function(id){cloudPreview(id)};
afterListingLocationSaved=function(h,returnTo){listingSavedLocationId=h.id;goFlow(returnTo||'my/listings')};
function cloudProfile(){return `<form class="cloud-form" onsubmit="cloudSaveProfile(event)">${field('Таны нэр','name',cloud.user.name,'text','required maxlength="60"')}<p>${esc(cloud.user.email)}</p><p class="notice">Имэйл ${cloud.user.emailVerified?'баталгаажсан':'баталгаажаагүй'}. DAN баталгаажуулалт хийгдээгүй.</p><p data-cloud-error class="cloud-error" role="alert" hidden></p><button class="primary" type="submit">Хадгалах</button></form><details class="cloud-password"><summary>Нууц үг солих</summary><form class="cloud-form" onsubmit="cloudChangePassword(event)">${field('Одоогийн нууц үг','currentPassword','','password','required autocomplete="current-password"')}${field('Шинэ нууц үг','password','','password','required minlength="15" maxlength="128" autocomplete="new-password"')}<p data-cloud-error role="alert" hidden></p><button class="primary" type="submit">Нууц үг солих</button></form></details>`}
async function cloudSaveProfile(event){event.preventDefault();const form=event.target;cloudPendingForm(form,true);try{const result=await cloudAPI('/auth/profile',{method:'PATCH',body:Object.fromEntries(new FormData(form))});cloud.user=result.user;refreshAccount();toast('Хадгаллаа')}catch(error){cloudFormError(form,error)}finally{cloudPendingForm(form,false)}}
async function cloudChangePassword(event){event.preventDefault();const form=event.target;cloudPendingForm(form,true);try{const result=await cloudAPI('/auth/password',{method:'POST',body:Object.fromEntries(new FormData(form))});cloud.csrf=result.csrf;form.reset();toast('Нууц үг шинэчлэгдлээ. Бусад төхөөрөмжөөс гарлаа.')}catch(error){cloudFormError(form,error)}finally{cloudPendingForm(form,false)}}
function cloudMy(sub){if(!cloud.user)return cloudGate();const menu=[['listings','Миний зарууд'],['messages','Лавлагаа'],['profile','Миний мэдээлэл']].map(([key,label])=>`<a class="${sub===key?'active':''}" href="#/my/${key}">${label}</a>`).join('');if(sub==='posts')return cloudPage('Миний нийтлэлүүд',cloudRecords('posts'),menu);if(sub==='profile')return cloudPage('Миний мэдээлэл',cloudProfile(),menu);if(sub==='listings'){const entry=cloudLoad('/me/listings?limit=30');if(entry.data)flowState.listings=entry.data.items;return cloudPage('Миний зарууд','<p><a class="button-link primary" href="#/listing/new">+ Зар нэмэх</a></p>'+cloudListingRows(entry),menu)}return cloudPage('Лавлагаа',cloudRecords('inquiries',false),menu)}
save=async function(id,event){event?.stopPropagation();if(!cloud.user){goFlow('login');return}const exists=saved.includes(id);try{await cloudAPI('/favorites',{method:exists?'DELETE':'POST',body:{id}});saved=exists?saved.filter(n=>n!==id):[...saved,id];render()}catch(error){toast(cloudError(error))}};
contact=function(id,kind){const h=homes.find(h=>h.id===id);if(kind==='phone'){if(h?.showContactPhone&&h.contactPhone)modal(`<h2>Утас</h2><a class="button-link" href="tel:${esc(h.contactPhone.replace(/[^+\d]/g,''))}">${esc(h.contactPhone)}</a>`);else toast('Зар оруулагч утсаа нийтэд харуулаагүй. Мессежээр лавлана уу.');return}if(!cloud.user){goFlow('login');return}cloudRecordForm('inquiries',null,id)};
report=function(id){if(!cloud.user){goFlow('login');return}cloudRecordForm('reports',null,id)};
function cloudRecords(kind,editable=true,admin=false){const path=admin?'/admin/records/'+kind:'/records/'+kind+(kind==='notices'&&!editable?'':'?mine=1'),entry=cloudLoad(path);if(!entry.data)return cloudNotice(entry);return `${editable&&!admin?`<p><button class="primary" onclick="cloudRecordForm('${kind}')">+ Нэмэх</button></p>`:''}<div class="cloud-records">${entry.data.items.map(r=>`<article><div>${cloudBadge(r.status)} <small>${esc(r.createdAt.slice(0,10))}</small></div><h3>${esc(r.title)}</h3><p class="listing-user-text">${esc(r.message||'')}</p>${r.propertyId?`<button onclick="cloudInspect(${Number(r.propertyId)})">Зар № ${Number(r.propertyId)}</button>`:''}${Object.entries(r).filter(([key,value])=>['phone','email','date','time','budget','price','stage','adminReply'].includes(key)&&value).map(([key,value])=>`<p><span class="muted">${esc(key)}</span> ${esc(value)}</p>`).join('')}${editable&&!admin?`<button onclick="cloudRecordForm('${kind}','${r.id}')">Засах</button><button onclick="cloudArchiveRecord('${kind}','${r.id}')">Архивлах</button>`:''}${admin?`<button onclick="cloudReviewRecord('${r.id}',${r.revision})">Хянах / хариулах</button>`:''}</article>`).join('')||emptyFlow('Мэдээлэл байхгүй','Шинэ мэдээлэл энд харагдана.')}</div>${entry.data.cursor?`<button onclick="cloudMoreResource('${path}')">Дараах</button>`:''}`}
function cloudRecordForm(kind,id=null,propertyId=null){const records=cloud.cache.get('/records/'+kind+'?mine=1')?.data?.items||[],r=records.find(r=>r.id===id)||{};modal(`<h2>${esc(cloudLabels[kind])}</h2><form class="cloud-form" onsubmit="cloudSaveRecord(event,'${kind}','${id||''}',${propertyId||r.propertyId||'null'})">${field('Гарчиг / Нэр','title',r.title||'','text','required maxlength="120"')}<label class="field">Тэмдэглэл / Мессеж<textarea name="message" maxlength="4000">${esc(r.message||'')}</textarea></label>${['clients','consultations','schedules','contracts','ledger','groups','campaigns'].includes(kind)?field('Утас','phone',r.phone||'')+field('Имэйл','email',r.email||'','email')+field('Огноо','date',r.date||'','date')+field('Дүн / Төсөв, ₮','budget',r.budget||'','number','min="0"')+field('Өөрийн зарын дугаар','propertyId',r.propertyId||'','number','min="1"'):''}${kind==='posts'?'<input name="province" type="hidden" value="Улаанбаатар"><input name="area" type="hidden" value="'+esc(flowState.neighborhood?.area||'Сүхбаатар')+'">':''}<input name="revision" type="hidden" value="${r.revision||0}"><p data-cloud-error role="alert" class="cloud-error" hidden></p><button class="primary" type="submit">Илгээх / Хадгалах</button>${kind==='campaigns'?'<p class="notice">Энэ нь байршуулалтын хүсэлт. Төлбөр автоматаар хасагдахгүй.</p>':''}</form>`)}
async function cloudSaveRecord(event,kind,id,propertyId){event.preventDefault();const form=event.target,body=Object.fromEntries(new FormData(form));body.revision=Number(body.revision);if(propertyId)body.propertyId=propertyId;cloudPendingForm(form,true);try{await cloudAPI('/records/'+kind+(id?'/'+id:''),{method:id?'PUT':'POST',body});cloudInvalidate();closeOverlay();render();toast('Серверт хадгаллаа')}catch(error){cloudFormError(form,error)}finally{cloudPendingForm(form,false)}}
async function cloudArchiveRecord(kind,id){try{await cloudAPI('/records/'+kind+'/'+id,{method:'DELETE'});cloudInvalidate();render()}catch(error){toast(cloudError(error))}}
function cloudOrgForm(){const entry=cloudLoad('/organization');if(!entry.data)return cloudNotice(entry);const org=entry.data.item||{};return `${cloudBadge(org.status||'pending')}<p class="notice">Бүртгэл, зөвшөөрөл, төлөөлөх эрх болон оффисын нотолгоог хоёр эрх бүхий ажилтан тусад нь шалгасны дараа баталгаажуулна. DAN холбогдоогүй.</p><form class="cloud-form" onsubmit="cloudSaveOrg(event)">${[['name','Байгууллагын нэр'],['agent','Хариуцсан ажилтан'],['phone','Утас'],['email','Имэйл'],['address','Оффисын хаяг'],['registration','Бүртгэлийн дугаар'],['licenseNumber','Зөвшөөрлийн дугаар'],['licenseValidUntil','Зөвшөөрөл хүчинтэй огноо'],['businessHours','Ажлын цаг']].map(([key,label])=>field(label,key,org[key]||'',key==='licenseValidUntil'?'date':key==='email'?'email':'text',['name','agent','address','registration','licenseNumber','licenseValidUntil'].includes(key)?'required':'')).join('')}<label class="field">Танилцуулга<textarea name="description" maxlength="1500">${esc(org.description||'')}</textarea></label>${['registry','license','authority','office'].map(key=>field(({registry:'Улсын бүртгэл',license:'Зөвшөөрөл',authority:'Төлөөлөх эрх',office:'Оффис'})[key]+' · нотолгооны лавлагаа','ref_'+key,org.refs?.[key]||'','text','required maxlength="200"')).join('')}${field('Өргөрөг','latitude',org.latitude??'','number','step="any" min="41" max="53"')}${field('Уртраг','longitude',org.longitude??'','number','step="any" min="87" max="120"')}<label><input name="showPhone" type="checkbox" ${org.showPhone?'checked':''}>Утсыг нийтэд харуулах</label><label><input name="showEmail" type="checkbox" ${org.showEmail?'checked':''}>Имэйлийг нийтэд харуулах</label><input name="revision" type="hidden" value="${org.revision||0}"><p data-cloud-error role="alert" class="cloud-error" hidden></p><button class="primary" type="submit">Хяналтад илгээх</button></form>`}
async function cloudSaveOrg(event){event.preventDefault();const form=event.target,f=new FormData(form),body=Object.fromEntries(f);body.refs=Object.fromEntries(['registry','license','authority','office'].map(k=>[k,f.get('ref_'+k)]));body.showPhone=f.has('showPhone');body.showEmail=f.has('showEmail');body.revision=Number(body.revision);cloudPendingForm(form,true);try{await cloudAPI('/organization',{method:'PUT',body});cloudInvalidate();render();toast('Байгууллагын мэдээлэл хяналтад илгээгдлээ')}catch(error){cloudFormError(form,error)}finally{cloudPendingForm(form,false)}}
function cloudPro(sub){if(!cloud.user)return cloudGate();const links=[['dashboard','Ажлын самбар'],['listings','Миний зарууд'],['new','Зар нэмэх'],['office','Байгууллага / Нийтийн профайл'],...Object.entries(cloudLabels).filter(([k])=>['clients','consultations','schedules','contracts','ledger','groups','campaigns','inquiries'].includes(k))];const menu=links.map(([key,label])=>`<a class="${sub===key?'active':''}" href="#/pro/${key}">${label}</a>`).join('');if(sub==='new'){const entry=cloudLoad('/organization');if(!entry.data)return cloudPage('Зар нэмэх',cloudNotice(entry),menu);if(!entry.data.item)return cloudPage('Эхлээд байгууллагаа бүртгүүлнэ үү','<a class="button-link primary" href="#/pro/office">Байгууллага бүртгүүлэх</a>',menu);if(!Object.keys(flowState.draft||{}).length){const org=entry.data.item;flowState.draft={contactRole:'agent',agencyName:org.name,contactName:org.agent,contactPhone:org.phone||'',returnTo:'pro/listings',currency:'MNT'}}return renderListingEditor()};if(['office','settings','verification'].includes(sub))return cloudPage('Байгууллагын мэдээлэл',cloudOrgForm(),menu);if(sub==='listings'){const entry=cloudLoad('/me/listings?limit=30');if(entry.data)flowState.listings=entry.data.items;return cloudPage('Миний зарууд',cloudListingRows(entry),menu)}if(cloudLabels[sub])return cloudPage(cloudLabels[sub],cloudRecords(sub),menu);return cloudPage('Өрөө PRO',`<div class="cloud-welcome"><h2>${esc(cloud.user.name)}, тавтай морил!</h2><p>Зар, харилцагч, лавлагаа болон ажлын бүртгэлээ нэг дороос удирдаарай.</p><a class="button-link primary" href="#/pro/new">+ Зар нэмэх</a><a class="button-link" href="#/pro/office">Байгууллага бүртгүүлэх</a></div><p class="notice">Гэрээ, санхүүгийн бүртгэл нь дотоод тэмдэглэл. Цахим гэрээ байгуулах, төлбөр шилжүүлэх үйлчилгээ холбогдоогүй.</p>`,menu)}
function cloudAdmin(sub){if(!cloud.user)return cloudGate();if(!['admin','moderator'].includes(cloud.user.role))return cloudPage('Нэвтрэх эрхгүй',emptyFlow('Зөвхөн эрх бүхий ажилтан','Таны бүртгэлд админы эрх олгогдоогүй.'));const links=[['overview','Ерөнхий самбар'],['listings','Зарын хяналт'],['brokers','Зуучлагчид'],...(cloud.user.role==='admin'?[['users','Хэрэглэгчид']]:[]),['reports','Мэдээлсэн зарууд'],['support','Тусламж'],['posts','Хөршүүдийн түүх'],['notices','Мэдээ'],['campaigns','Зар сурталчилгаа'],...(cloud.user.role==='admin'?[['journal','Өрөө JOURNAL']]:[]),['audit','Үйлдлийн түүх']];const menu=links.map(([key,label])=>`<a class="${sub===key?'active':''}" href="#/admin/${key}">${label}</a>`).join('');let body;
 if(sub==='listings')body=cloudListingRows(cloudLoad('/admin/listings?limit=30'),true);
 else if(sub==='brokers'){const entry=cloudLoad('/admin/organizations');body=entry.data?`<div class="cloud-records">${entry.data.items.map(org=>`<article><h2>${esc(org.name)}</h2>${cloudBadge(org.status)}<p>${esc(org.agent)} · ${esc(org.phone||'')}</p><p>${esc(org.address)}</p><p>Бүртгэл: ${esc(org.registration)} · Зөвшөөрөл: ${esc(org.licenseNumber)}</p>${Object.entries(org.refs||{}).map(([key,value])=>`<p>${esc(key)}: ${esc(value)}</p>`).join('')}<button onclick="cloudReviewOrg('${org.id}',${org.revision},'${org.status}')">Баримт шалгах</button></article>`).join('')||emptyFlow('Байгууллага бүртгэгдээгүй','Шинээр бүртгүүлсэн байгууллага энд харагдана.')}</div>`:cloudNotice(entry)}
 else if(sub==='users'){const entry=cloudLoad('/admin/users');body=entry.data?`<div class="cloud-records">${entry.data.items.map(u=>`<article><b>${esc(u.name)}</b><p>${esc(u.email)} · ${esc(u.role)} · ${esc(u.status)}</p>${u.role!=='admin'?`<button onclick="cloudStaffRole('${u.id}','${u.role}')">Шалгах ажилтны эрх</button>`:''}${u.role==='user'?`<button onclick="cloudUserStatus('${u.id}','${u.status==='blocked'?'active':'blocked'}')">${u.status==='blocked'?'Нээх':'Түр хаах'}</button>`:''}</article>`).join('')}</div>`:cloudNotice(entry)}
 else if(sub==='audit'){const entry=cloudLoad('/admin/audit');body=entry.data?`<div class="cloud-records">${entry.data.items.map(r=>`<article><b>${esc(r.action)}</b><p>${esc(r.target_type)} · ${esc(r.target_id)} · ${esc(r.created_at)}</p><code>${esc(r.detail)}</code><small>${esc(r.request_id)}</small></article>`).join('')}</div>`:cloudNotice(entry)}
 else if(cloudLabels[sub])body=cloudRecords(sub,false,true)+(sub==='notices'?'<button onclick="cloudRecordForm(\'notices\')">+ Мэдээ бичих</button>':'');
 else{const entry=cloudLoad('/admin/summary');body=entry.data?`<div class="cloud-stats"><article><span>Хэрэглэгчид</span><b>${entry.data.users}</b></article><article><span>Зарууд</span><b>${entry.data.listings.reduce((s,r)=>s+r.count,0)}</b></article><article><span>Хяналт хүлээж буй зар</span><b>${entry.data.listings.filter(r=>r.moderation==='pending'&&r.state==='published').reduce((s,r)=>s+r.count,0)}</b></article><article><span>Байгууллагууд</span><b>${entry.data.organizations.reduce((s,r)=>s+r.count,0)}</b></article></div><p class="notice">Бодит серверийн тоо. Админы эрх, зөвшөөрөл болон үйлдлийн түүх серверээр шалгагдана.</p>`:cloudNotice(entry)}return cloudPage(links.find(([key])=>key===sub)?.[1]||'Өрөө ADMIN',body,menu)
}
function cloudReviewListing(id,revision){modal(`<h2>Зарын хяналт · № ${id}</h2><form class="cloud-form" onsubmit="cloudSubmitReview(event,'/admin/listings/${id}/review',${revision})"><label class="field">Шийдвэр<select name="status"><option value="approved">Батлах</option><option value="pending">Хяналтад үлдээх</option><option value="rejected">Татгалзах</option><option value="suspended">Түр зогсоох</option></select></label><label class="field">Шалтгаан<textarea name="reason" required maxlength="1000"></textarea></label><p data-cloud-error role="alert" hidden></p><button type="submit" class="primary">Шийдвэр хадгалах</button></form>`)}
function cloudReviewOrg(id,revision,status){const first=['pending','rejected'].includes(status);modal(`<h2>Байгууллагын шалгалт</h2><p>Нэг ажилтан өөрийн анхны шалгалтыг эцэслэн батлах боломжгүй.</p><form class="cloud-form" onsubmit="cloudSubmitReview(event,'/admin/organizations/${id}/review',${revision})"><label class="field">Шат<select name="step"><option value="${first?'first':'final'}">${first?'Анхны баримтын шалгалт':'Хараат бус эцсийн шалгалт'}</option><option value="reject">Татгалзах</option><option value="suspend">Түр зогсоох</option></select></label>${first?['registry','license','authority','identity','office','contact'].map(key=>`<label><input type="checkbox" name="check_${key}">${esc(({registry:'Улсын бүртгэл',license:'Зөвшөөрөл',authority:'Төлөөлөх эрх',identity:'Хувийн мэдээлэл',office:'Бодит оффис',contact:'Баталгаажсан холбоо'})[key])} шалгасан</label>${field('Нотолгооны лавлагаа','ref_'+key,'','text','maxlength="200"')}`).join(''):`<label><input name="independent" type="checkbox">Бие даан давхар шалгасан</label>${field('Хүчинтэй огноо (90 хоног хүртэл)','validUntil','','date')}`}<label class="field">Шалтгаан / Шалгалтын тэмдэглэл<textarea name="reason" required maxlength="1000"></textarea></label><p data-cloud-error role="alert" hidden></p><button class="primary" type="submit">Хадгалах</button></form>`)}
function cloudReviewRecord(id,revision){modal(`<h2>Хяналт / Хариу</h2><form class="cloud-form" onsubmit="cloudSubmitReview(event,'/admin/records/${id}/review',${revision})"><label class="field">Төлөв<select name="status"><option value="progress">Шийдвэрлэж байна</option><option value="resolved">Шийдвэрлэсэн</option><option value="published">Нийтлэх</option><option value="rejected">Татгалзах</option><option value="archived">Архивлах</option></select></label><label class="field">Шалтгаан / Хариу<textarea name="reason" required maxlength="1000"></textarea></label><p data-cloud-error role="alert" hidden></p><button type="submit" class="primary">Хадгалах</button></form>`)}
async function cloudSubmitReview(event,path,revision){event.preventDefault();const form=event.target,f=new FormData(form),body={...Object.fromEntries(f),revision,independent:f.has('independent'),checks:{},refs:{}};for(const key of ['registry','license','authority','identity','office','contact']){body.checks[key]=f.has('check_'+key);body.refs[key]=f.get('ref_'+key)||''}cloudPendingForm(form,true);try{await cloudAPI(path,{method:'POST',body});cloudInvalidate();closeOverlay();render();toast('Шийдвэр серверт хадгалагдлаа')}catch(error){cloudFormError(form,error)}finally{cloudPendingForm(form,false)}}
function cloudUserStatus(id,status){modal(`<h2>Хэрэглэгчийн төлөв</h2><form class="cloud-form" onsubmit="cloudSubmitReview(event,'/admin/users/${id}/status',0)"><input name="status" type="hidden" value="${status}"><label class="field">Шалтгаан<textarea name="reason" required></textarea></label><p data-cloud-error role="alert" hidden></p><button class="primary" type="submit">${status==='blocked'?'Түр хаах':'Нээх'}</button></form>`)}
officeIdentity=function(h){return h?.cloud&&h.brokerId?{officeId:h.brokerId}:null};
officePublicModel=function(id){return cloud.cache.get('/offices/'+id)?.data?.office||null};
brokerVerificationBadge=function(id){const h=homes.find(h=>h.brokerId===id&&h.brokerVerified);return h?'<span class="cloud-badge approved">'+icon('shield-check')+'Баталгаажсан зуучлагч</span>':''};
officeListingCard=function(h){if(!h.brokerId)return `<div class="office-owner-card"><b>Зар оруулагч</b>${listingContactRows(h)}</div>`;return `<article class="office-detail-card"><a class="office-detail-title" href="#/offices/${esc(h.brokerId)}">${icon('briefcase')}<div><b>${esc(h.agencyName||'Зуучлалын байгууллага')}</b>${brokerVerificationBadge(h.brokerId)}</div>${icon('chevron-right')}</a><p>Байгууллагын танилцуулга, холбоо барих мэдээлэл болон бүх зарыг үзэх</p><a href="#/offices/${esc(h.brokerId)}">Нийтийн профайл →</a></article>`};
officeRelatedLink=function(h){return h.brokerId?`<a class="detail-external-link" href="#/offices/${esc(h.brokerId)}">Байгууллагын бүх зар →</a>`:''};
function cloudOffices(id){const path=id?'/offices/'+id:'/offices',entry=cloudLoad(path);if(!entry.data)return cloudPage('Зуучлалын байгууллагууд',cloudNotice(entry));if(!id)return cloudPage('Зуучлалын байгууллагууд',`<div class="cloud-records">${entry.data.items.map(o=>`<article><h2>${esc(o.name)}</h2><span class="cloud-badge approved">Баталгаажсан зуучлагч</span><p>${esc(o.address)}</p><a href="#/offices/${o.id}">Профайл болон зарууд →</a></article>`).join('')||emptyFlow('Баталгаажсан байгууллага байхгүй','Хяналтаар батлагдсан байгууллагууд энд харагдана.')}</div>`);const o=entry.data.office;return cloudPage(o.name,`<section class="cloud-office"><span class="cloud-badge approved">Баталгаажсан зуучлагч · ${esc(o.validUntil)}</span><h2>${esc(o.agent)}</h2><p class="listing-user-text">${esc(o.description)}</p>${listingRows([['Хаяг',o.address],['Ажлын цаг',o.businessHours],['Утас',o.phone],['Имэйл',o.email]])}</section><h2>Байгууллагын зарууд</h2><div class="cards">${entry.data.listings.items.map(card).join('')||emptyFlow('Зар байхгүй','Батлагдсан, нийтэд нээлттэй зарууд энд харагдана.')}</div>${entry.data.listings.cursor?`<button onclick="cloudMoreOffice('${id}')">Дараах зарууд</button>`:''}`)}
async function cloudMoreOffice(id){const path='/offices/'+id,entry=cloud.cache.get(path);try{const next=await cloudAPI(path+'?cursor='+encodeURIComponent(entry.data.listings.cursor));entry.data.listings={...next.listings,items:[...entry.data.listings.items,...next.listings.items]};cloudRemember(next.listings.items);render()}catch(error){toast(cloudError(error))}}
function cloudCommunity(){const area=flowState.neighborhood?.area||'Сүхбаатар',params='?province='+encodeURIComponent('Улаанбаатар')+'&area='+encodeURIComponent(area),summary=cloudLoad('/regions/summary'+params),posts=cloudLoad('/records/posts'+params);return cloudPage('Манай хороолол',`<label class="field">Дүүрэг<select onchange="flowState.neighborhood={area:this.value};render()">${Object.keys(UB_KHOROO_COUNTS).map(a=>`<option ${a===area?'selected':''}>${a}</option>`).join('')}</select></label><h2>${esc(area)} · Хорооллын мэдээлэл</h2>${summary.data?`<div class="cloud-stats"><article><span>Нийтэд нээлттэй зар</span><b>${summary.data.total}</b></article>${summary.data.groups.filter(g=>g.deal==='rent').slice(0,3).map(g=>`<article><span>${esc(types[g.type])} · ${g.rooms||'—'} өрөө · ${g.count} зарын дундаж санал үнэ</span><b>${formatMnt(Math.round(g.averagePrice||0))}</b><small>${esc(optionText('period',g.rentPeriod))}</small></article>`).join('')}</div>`:cloudNotice(summary)}<p class="notice">Үнэ нь нийтлэгдсэн зарын санал үнийн дундаж. Бодит хэлцлийн үнэ биш. Орчны үйлчилгээний баталгаатай мэдээлэл хараахан ороогүй.</p><h2>Хөршүүдийн түүх</h2><button onclick="${cloud.user?"cloudRecordForm('posts')":"goFlow('login')"}">Түүх бичих</button>${posts.data?`<div class="cloud-records">${posts.data.items.map(p=>`<article><h3>${esc(p.title)}</h3><p>${esc(p.message)}</p><small>${esc(p.createdAt.slice(0,10))}</small></article>`).join('')||emptyFlow('Нийтлэл байхгүй','Шалгагдсан нийтлэлүүд энд харагдана.')}</div>`:cloudNotice(posts)}`)}
flowRoute=function(parts){if(!cloud.ready)return '<div class="wrap"><div class="empty" role="status">Сервертэй холбогдож байна…</div></div>';const [route,sub]=parts;if(route.startsWith('activate-admin'))return cloudAuth('activate-admin');if(route==='login')return cloudAuth(sub);if(route==='my')return cloudMy(sub||'listings');if(route==='pro')return cloudPro(sub||'dashboard');if(route==='admin')return cloudAdmin(sub||'overview');if(route==='listing')return cloud.user?renderListingEditor():cloudGate();if(route==='offices')return cloudOffices(sub);if(route==='community')return cloudCommunity();if(route==='favorites'){if(!cloud.user)return cloudGate();const entry=cloudLoad('/me/favorites?limit=30');return cloudPage('Сонирхсон зарууд',entry.data?'<div class="cards">'+(entry.data.items.map(card).join('')||emptyFlow('Хадгалсан зар байхгүй','Таалагдсан зарын зүрхийг дараарай.'))+'</div>'+(entry.data.cursor?'<button onclick="cloudMoreResource(\'/me/favorites?limit=30\')">Дараах</button>':''):cloudNotice(entry))}if(['complex','complexes','sale'].includes(route))return cloudPage('Хотхон / Шинэ төсөл',emptyFlow('Баталгаажсан мэдээлэл бэлтгэгдэж байна','Одоогоор нийтэд нээлттэй заруудаас хайх боломжтой.','<a href="#/map">Газрын зураг дээр хайх</a>'));if(route==='agent')return cloudPro('dashboard');if(route==='about')return cloudPage('Өрөө платформ','<p>Монголд орон сууц, хаус, оффис, газар болон түрээсийн орон зай хайх, зарлах платформ. Зар, зураг болон лавлагаа серверт хадгалагдана.</p>');if(route==='inquiry')return cloud.user?cloudPage('Хэрэглэгчийн тусламж',cloudRecords('support')):cloudGate();if(route==='notice')return cloudPage('Мэдээ',cloudRecords('notices',false));if(route==='privacy'||route==='terms')return cloudPage(route==='privacy'?'Нууцлалын мэдээлэл':'Үйлчилгээний мэдээлэл','<p>Бүртгэл, зар, зургууд болон таны илгээсэн хүсэлт Cloudflare серверийн D1 / R2 санд хадгалагдана. Нэвтрэлтийн cookie HttpOnly байна. Нийтлэхээр сонгосон мэдээлэл хяналтын дараа нийтэд харагдана.</p><p>Төлбөр, цахим гэрээ болон DAN холболт идэвхжээгүй. Арилжааны үйлчилгээг нийтэд эхлүүлэхээс өмнө албан ёсны нөхцөл, мэдээлэл хамгаалалтын бодлогыг баталгаажуулна.</p>');return cloudOriginal.flowRoute(parts)};
captureListingDraft=function(form){const d=cloudOriginal.capture(form);if(Number(form.dataset.editorStep)===2)d.showContactPhone=new FormData(form).has('showContactPhone');return d};
renderListingEditor=function(){let html=cloudOriginal.editor();html=html.replace('Демо зарыг хадгалах','Хяналтад илгээх').replace('Демо горим · Зар нийтэд илгээгдэхгүй.','Зар серверт хадгалагдаж, хяналтын дараа нийтэд харагдана.').replaceAll('Энэ браузерт түр хадгална','Ноорог энэ төхөөрөмж дээр; зураг серверт хадгалагдана.').replaceAll('Энэ браузерт','Энэ төхөөрөмж дээр').replace('Мэдээллээ шалгасан. Энэ нь зөвхөн браузерт хадгалагдах демо зар гэдгийг ойлгосон.','Оруулсан мэдээлэл болон зургуудаа шалгасан. Зар хяналтын дараа нийтэд харагдахыг ойлгосон.').replace('Оруулбал зарын холбоо барих хэсэгт харагдана.','Доорх сонголтыг тэмдэглэвэл утас нийтэд харагдана.');if(listingStep===2)html=html.replace('<div class="editor-errors"',`<label class="cloud-phone-consent"><input type="checkbox" name="showContactPhone" ${flowState.draft.showContactPhone?'checked':''}>Утасны дугаараа нийтэд харуулах</label><div class="editor-errors"`);return html};
syncListingPhotos=function(){flowState.draft.photoIds=listingPhotoDraft.map(src=>src.match(/^\/api\/media\/([a-f0-9-]{36})\/full$/)?.[1]).filter(Boolean);cloudOriginal.sync()};
async function cloudJPEG(file,maxEdge,quality,limit){const bitmap=await createImageBitmap(file);try{if(bitmap.width*bitmap.height>60000000)throw new Error('Зураг хэт том байна.');const scale=Math.min(1,maxEdge/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);let blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));if(!blob||blob.size>limit)blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.55));if(!blob||blob.size>limit)throw new Error('Зураг шахсаны дараа хэт том байна.');return blob}finally{bitmap.close()}}
readEditorPhotos=async function(input){const files=Array.from(input.files||[]);if(!cloud.user||editorPhotoBusy)return;if(files.length+listingPhotoDraft.length>10||files.some(f=>f.size>8*1024*1024||!['image/jpeg','image/png'].includes(f.type))){toast('10 хүртэл JPEG / PNG зураг. Нэг зураг 8 MB хүртэл.');return}editorPhotoBusy=true;let done=0;const status=document.getElementById('listing-photo-status'),results=new Array(files.length),errors=[];const queue=files.map((file,index)=>({file,index}));async function upload(){while(queue.length){const {file,index}=queue.shift();try{if(status)status.textContent=`Зураг байршуулж байна · ${done} / ${files.length}`;const full=await cloudJPEG(file,1920,.82,2*1024*1024),thumb=await cloudJPEG(file,480,.75,200*1024),key=crypto.randomUUID();let started;for(let attempt=0;attempt<2;attempt++){try{started=await cloudAPI('/uploads/start',{method:'POST',body:{requestKey:key}});for(const [variant,blob] of [['full',full],['thumb',thumb]])if(!started[variant+'Ready'])await cloudAPI('/uploads/'+started.item.id+'/'+variant,{method:'PUT',body:blob});break}catch(error){if(attempt||error.status&&error.status<500&&error.status!==429)throw error}}results[index]=started.item.fullUrl}catch(error){errors.push(file.name+': '+cloudError(error))}finally{done++;if(status)status.textContent=`${done} / ${files.length} зураг боловсрууллаа`}}}try{await Promise.all([upload(),upload()]);listingPhotoDraft.push(...results.filter(Boolean));syncListingPhotos();if(status)status.textContent=errors.length?errors.join(' · ')+' · Алдаатай зургийг дахин сонгоно уу.':listingPhotoDraft.length+' зураг серверт хадгалагдлаа.'}finally{editorPhotoBusy=false;input.value=''}};
submitListingEditor=async function(event){if(listingStep<3)return cloudOriginal.submit(event);event.preventDefault();if(cloud.saving)return;const d=prepareListingDraft();for(let step=0;step<3;step++){const errors=validateListingDraft(d,step);if(errors.length){listingStep=step;render();showListingErrors(errors);return}}if(!new FormData(event.target).has('ack')){showListingErrors([{field:'ack',message:'Мэдээллээ шалгаж баталгаажуулна уу.'}]);return}d.requestKey=d.requestKey||crypto.randomUUID();d.photoIds=listingPhotoDraft.map(src=>src.match(/^\/api\/media\/([a-f0-9-]{36})\/full$/)?.[1]).filter(Boolean);persistFlows();const body={...buildListingRecord(d),requestKey:d.requestKey,photoIds:d.photoIds,revision:d.revision,showContactPhone:!!d.showContactPhone};delete body.photos;cloud.saving=true;cloudPendingForm(event.target,true);try{const result=await cloudAPI('/listings'+(d.editId?'/'+d.editId:''),{method:d.editId?'PUT':'POST',body});cloudRemember([result.item]);flowState.draft={};listingPhotoDraft=[];listingStep=0;editorReady=false;persistFlows();cloudInvalidate();await cloudLoadOwn();afterListingLocationSaved(result.item,d.returnTo||'my/listings');toast('Зар серверт хадгалагдлаа · Хяналт хүлээж байна')}catch(error){showListingErrors([{field:'save',message:cloudError(error)}])}finally{cloud.saving=false;cloudPendingForm(event.target,false)}};
function cloudSearchParams(){const p=new URLSearchParams({limit:'30',sort});if(category>=0&&location.hash.startsWith('#/map'))p.set('type',category);if(query.trim())p.set('q',query.trim());if(filter.deal!=='all')p.set('deal',filter.deal);for(const [from,to] of [['minRent','minPrice'],['max','maxPrice'],['minDeposit','minDeposit'],['maxDeposit','maxDeposit'],['minSize','minSize'],['maxSize','maxSize'],['floor','minFloor'],['maxFloor','maxFloor'],['year','minYear']])if(filter[from])p.set(to,filter[from]);for(const key of ['parking','elevator','pet','balcony','furnished'])if(filter[key])p.set(key,'1');if(filter.includeFee)p.set('includeFee','1');if(filter.rooms?.length)p.set('rooms',filter.rooms.map(v=>v==='5+'?'5':v).join(','));if(filter.garage&&filter.garage!=='all')p.set('garage',filter.garage==='yes'?'1':'0');if(filter.locations?.length)p.set('locations',JSON.stringify(filter.locations));if(cloud.bounds&&location.hash.startsWith('#/map'))p.set('bounds',cloud.bounds.join(','));if(!location.hash||location.hash==='#/'){if(activeTag===1)p.set('rooms','1');if(activeTag===2)p.set('deal','sale');if(activeTag===3)p.set('balcony','1');if(activeTag===4)p.set('type','4');if(activeTag===5)p.set('sort','new')}return p}
filtered=function(){return cloud.items.filter(isPublicListing)};
async function cloudSearch(append=false){const params=cloudSearchParams(),key=params.toString();if(!append&&cloud.searchKey===key&&Date.now()-cloud.searchUpdated<30000)return;if(append&&!cloud.cursor)return;cloud.searchAbort?.abort();const controller=new AbortController();cloud.searchAbort=controller;cloud.searchKey=key;cloud.searchUpdated=0;if(append)params.set('cursor',cloud.cursor);try{const result=await cloudAPI('/listings?'+params,{signal:controller.signal});if(controller.signal.aborted)return;cloud.items=append?[...cloud.items,...result.items]:result.items;cloud.cursor=result.cursor;cloud.searchUpdated=Date.now();cloud.error='';cloudRemember(result.items);cloudOriginal.render();cloudAfterRender()}catch(error){if(error.name==='AbortError')return;cloud.error=cloudError(error);cloudAfterRender()}}
propertyMapMarkup=function(){return cloudOriginal.mapMarkup().replace('Дүүргийн нэр · Жишээ зарын тоо','Зарын байршил · Нийтэд нээлттэй зарын тоо')};
initializePropertyMap=function(){const el=document.getElementById('property-map');if(!el)return;if(typeof maplibregl==='undefined'){document.querySelector('.map-loading').textContent='Газрын зураг ачаалсангүй. Дахин ачаална уу.';return}try{propertyMap=new maplibregl.Map({container:el,style:'https://tiles.openfreemap.org/styles/liberty',center:mapView?.center||MAP_REGION.center,zoom:mapView?.zoom??10.5,minZoom:3,maxZoom:18});const map=propertyMap;map.on('load',()=>{document.querySelector('.map-loading')?.setAttribute('hidden','');cloudCluster(map)});map.on('moveend',()=>{mapView={center:map.getCenter(),zoom:map.getZoom()};const b=map.getBounds(),next=[Math.max(87,b.getWest()),Math.max(41,b.getSouth()),Math.min(120,b.getEast()),Math.min(53,b.getNorth())].map(v=>Number(v.toFixed(5)));if(next[0]>=next[2]||next[1]>=next[3])return;cloud.bounds=next;clearTimeout(cloud.mapTimer);cloud.mapTimer=setTimeout(()=>{cloudCluster(map);cloudSearch()},300)});if(typeof ResizeObserver!=='undefined'){mapResizeObserver=new ResizeObserver(()=>map.resize());mapResizeObserver.observe(el)}}catch{document.querySelector('.map-loading').textContent='Газрын зургийг ачаалж чадсангүй.'}};
async function cloudCluster(map){cloud.clusterAbort?.abort();const clusterAbort=new AbortController();cloud.clusterAbort=clusterAbort;const params=cloudSearchParams();params.set('zoom',map.getZoom());try{const result=await cloudAPI('/map/clusters?'+params,{signal:clusterAbort.signal});if(clusterAbort.signal.aborted||propertyMap!==map)return;for(const marker of cloud.markers)marker.remove();cloud.markers=[];for(const item of result.items){const el=document.createElement('button');el.className='district-pill';el.innerHTML=`<b>${item.count}</b><span>${esc(item.area)}</span>`;el.setAttribute('aria-label',item.area+' · '+item.count+' зар');el.onclick=()=>item.count===1?detail(item.id):map.flyTo({center:[item.longitude,item.latitude],zoom:Math.min(18,map.getZoom()+2)});cloud.markers.push(new maplibregl.Marker({element:el}).setLngLat([item.longitude,item.latitude]).addTo(map))}if(result.truncated)document.querySelector('.map-demo-note').textContent='Илүү нарийвчлан харахын тулд ойртуулна уу.'}catch(error){if(error.name!=='AbortError'&&propertyMap===map)toast(cloudError(error))}}
detail=async function(id){let h=homes.find(h=>h.id===id);if(!h||!isPublicListing(h)){try{const result=await cloudAPI('/listings/'+id);cloudRemember([result.item]);h=result.item;if(!isPublicListing(h)){cloudInspect(id);return}}catch(error){toast(cloudError(error));return}}cloudOriginal.detail(id)};
listingDetailMarkup=function(h){return cloudOriginal.detailMarkup(h).replace(/(\/api\/media\/[a-f0-9-]{36})\/thumb/g,'$1/full').replaceAll('Демо · Бодит мессеж илгээгдэхгүй','Лавлагаа зар оруулагчийн бүртгэлд илгээгдэнэ').replace(/<p class="notice">Жишээ зар[\s\S]*?<\/p>/g,'').replaceAll('Эзэмшигч баталгаажуулсан · Демо','Зар оруулагчийн мэдээлэл')};
function cloudAfterRender(){document.documentElement.classList.add('cloud-ready');document.querySelector('footer .fine').textContent='Өрөө платформ · Бодит зар, зураг болон хүсэлт серверт хадгалагдана. Төлбөр / DAN үйлчилгээ холбогдоогүй.';document.querySelectorAll('.demo-label,.demo-banner,.demo-mark').forEach(el=>el.remove());const list=document.querySelector('.listing');if(list){const count=list.querySelector('.list-head b');if(count)count.textContent='Зарууд · '+cloud.items.length+(cloud.cursor?'+':'');let more=list.querySelector('.cloud-more');if(!more){more=document.createElement('div');more.className='cloud-more';list.append(more)}more.innerHTML=cloud.error?`<p role="alert">${esc(cloud.error)}</p><button onclick="cloudInvalidate();cloudSearch()">Дахин оролдох</button>`:cloud.cursor?'<button onclick="cloudSearch(true)">Дараах 30 зар</button>':''}const adminSub=location.hash.split('/')[2];const adminPath=adminSub==='brokers'?'/admin/organizations':adminSub==='users'?'/admin/users':null;if(adminPath&&cloud.cache.get(adminPath)?.data?.cursor){const content=document.querySelector('.cloud-content');if(content&&!content.querySelector('.cloud-more')){const button=document.createElement('button');button.className='cloud-more';button.textContent='Дараах 30';button.onclick=()=>cloudMoreResource(adminPath);content.append(button)}}if(location.hash.startsWith('#/map')&&activeDetail&&!document.querySelector('.detail-column'))detail(activeDetail)}
render=function(){if(location.hash&&!['#/'].includes(location.hash)&&!location.hash.startsWith('#/map')&&!location.hash.startsWith('#/sale'))cloud.searchAbort?.abort();cloudOriginal.render();cloudAfterRender();if(cloud.ready&&(!location.hash||location.hash==='#/'||location.hash.startsWith('#/map')||location.hash.startsWith('#/sale')))cloudSearch()};
async function cloudBoot(){homes.splice(0);saved=[];for(const key of Object.keys(flowState))delete flowState[key];Object.assign(flowState,{searches:[],bookmarks:[],complexSaved:[],complexRecent:[],requests:[],reports:[],posts:[],listings:[],profile:{name:'Зочин',demo:false},draft:{}});try{const prefs=JSON.parse(localStorage.getItem('oroo-search-preferences')||'{}');flowState.searches=prefs.searches||[];flowState.bookmarks=prefs.bookmarks||[]}catch{}try{const [status,session]=await Promise.all([cloudAPI('/health'),cloudAPI('/session')]);if(!status.ok)throw new Error('Серверийн холболт бүрэн биш.');cloud.user=session.user;cloud.csrf=session.csrf;if(cloud.user){flowState.profile={name:cloud.user.name,demo:false};try{flowState.draft=JSON.parse(localStorage.getItem(cloudDraftKey())||'{}')}catch{}await cloudLoadOwn()}cloud.ready=true;render()}catch(error){document.getElementById('app').innerHTML=`<div class="wrap cloud-gate"><h1>Сервертэй холбогдож чадсангүй</h1><p>${esc(cloudError(error))}</p><button onclick="location.reload()">Дахин оролдох</button></div>`;document.documentElement.classList.add('cloud-ready')}}

function cloudStaffRole(id,role){modal('<h2>Шалгах ажилтны эрх</h2><p>Хяналтын ажилтан зар, байгууллагын баримт болон хүсэлтүүдийг харах, шалгах эрхтэй болно. Хамтран ажиллагчийн бүртгэлийг нягтална уу.</p><form class="cloud-form" onsubmit="cloudSubmitReview(event,\'/admin/users/'+id+'/role\',0)"><label class="field">Эрх<select name="role"><option value="user">Хэрэглэгч</option><option value="moderator">Хяналтын ажилтан</option></select></label>'+field('Шалтгаан','reason','','text','required')+field('Таны одоогийн нууц үг','password','','password','required autocomplete="current-password"')+'<p data-cloud-error role="alert" hidden></p><button class="primary" type="submit">Эрх өөрчлөх</button></form>')}
Object.assign(window,{cloudStaffRole,cloudError,cloudAPI,cloudInvalidate,cloudLoad,cloudRemember,cloudNotice,cloudBadge,cloudPage,cloudGate,cloudFormError,cloudPendingForm,cloudDraftKey,cloudLogout,cloudAuth,cloudAuthenticate,cloudLoadOwn,cloudListingRows,cloudMoreResource,cloudArchiveListing,cloudArchiveConfirmed,cloudInspect,cloudPreview,cloudProfile,cloudSaveProfile,cloudChangePassword,cloudMy,cloudRecords,cloudRecordForm,cloudSaveRecord,cloudArchiveRecord,cloudOrgForm,cloudSaveOrg,cloudPro,cloudAdmin,cloudReviewListing,cloudReviewOrg,cloudReviewRecord,cloudSubmitReview,cloudUserStatus,cloudOffices,cloudMoreOffice,cloudCommunity,cloudJPEG,cloudSearchParams,cloudSearch,cloudCluster,cloudAfterRender,cloudBoot});
window.addEventListener('focus',()=>{if(cloud.ready&&(!location.hash||location.hash==='#/'||location.hash.startsWith('#/map')))cloudSearch()});
cloudBoot();
}
